∀ {size : ℕ} {profile : Core.FiniteBitRelationBarrier.Profile size} {Length : Type u_1} {lengthValue : Length → ℕ}
  {relation : Length → Fin size → Fin size → Bool} {Index : Type u_2}
  (table : Core.FiniteBitRelationBarrier.CertifiedTable profile Length lengthValue relation Index) (index : Index),
  Core.Finite.CertifiedTableAggregation.binaryRowRateFloor table index =
    if table.counts.storedFlat index = 0 then 0
    else ((table.counts.storedSafe index - 1) / table.counts.storedFlat index).log2

