∀ {object : Graph.FiniteObject} {family : Graph.TightVertexSuppression.CompatibleFamily object}
  {left right : family.suppressed.Vertex}
  {path : object.graph.Walk ↑(family.toRemaining left) ↑(family.toRemaining right)} {used : Option family.Index}
  {used_iff : ∀ (i : family.Index), used = some i ↔ family.chord i = s(left, right)}
  {length_eq : path.length = if used.isSome = true then 2 else 1}
  {support_none : used = none → path.support = [↑(family.toRemaining left), ↑(family.toRemaining right)]}
  {support_some :
    ∀ (i : family.Index),
      used = some i →
        path.support = [↑(family.toRemaining left), (family.configuration i).vertex, ↑(family.toRemaining right)]}
  {path_1 : object.graph.Walk ↑(family.toRemaining left) ↑(family.toRemaining right)} {used_1 : Option family.Index}
  {used_iff_1 : ∀ (i : family.Index), used_1 = some i ↔ family.chord i = s(left, right)}
  {length_eq_1 : path_1.length = if used_1.isSome = true then 2 else 1}
  {support_none_1 : used_1 = none → path_1.support = [↑(family.toRemaining left), ↑(family.toRemaining right)]}
  {support_some_1 :
    ∀ (i : family.Index),
      used_1 = some i →
        path_1.support = [↑(family.toRemaining left), (family.configuration i).vertex, ↑(family.toRemaining right)]},
  { path := path, used := used, used_iff := used_iff, length_eq := length_eq, support_none := support_none,
        support_some := support_some } =
      { path := path_1, used := used_1, used_iff := used_iff_1, length_eq := length_eq_1,
        support_none := support_none_1, support_some := support_some_1 } →
